<?php
declare(strict_types=1);
use CajunWebPro\Foundation\Provider\{ProviderOperation,TransportRequest,TransportResponse,OperationResult};
use CajunWebPro\Foundation\TwentyI\Operations\{DirectoryIndexingChange,TwentyIOperationRegister,TwentyIResultClassifier};
foreach(['ProviderOperation','TransportRequest','TransportResponse','OperationResult','TransportException'] as $class)require __DIR__.'/../../foundation/provider/'.$class.'.php';
foreach(['DirectoryIndexingChange','TwentyIOperation','TwentyIOperationRegister','TwentyIResultClassifier'] as $class)require __DIR__.'/../../foundation/twentyi-operations/'.$class.'.php';
$checks=[];
function dic_ok(string $name,bool $ok):void{global $checks;$checks[]=['name'=>$name,'passed'=>$ok];if(!$ok)throw new RuntimeException($name);}
function dic_refuses(callable $fn):bool{try{$fn();return false;}catch(InvalidArgumentException){return true;}}
try{
    foreach([1,42,999999999999999999] as $id)foreach([true,false] as $value){$op=new ProviderOperation(DirectoryIndexingChange::OPERATION,'synthetic-once',['packageId'=>$id,'value'=>$value]);$r=DirectoryIndexingChange::request($op);$label=$id.'/'.($value?'true':'false');dic_ok('Fixed method route and sole JSON boolean '.$label,$r->method==='POST'&&$r->url==='https://api.20i.com/package/'.$id.'/web/directoryIndexing'&&$r->body===json_encode(['value'=>$value])&&$r->timeoutSeconds===15.0);DirectoryIndexingChange::wire($r);dic_ok('Exact request passes its closed wire contract '.$label,true);}
    foreach([0,-1,1000000000000000000,'1',1.0,true,null] as $i=>$id)dic_ok('Invalid package identifier refused '.$i,dic_refuses(fn()=>DirectoryIndexingChange::params(['packageId'=>$id,'value'=>true])));
    foreach([null,0,1,'true','false',[],(object)[]] as $i=>$value)dic_ok('Nonboolean desired value refused '.$i,dic_refuses(fn()=>DirectoryIndexingChange::params(['packageId'=>1,'value'=>$value])));
    foreach([[],['packageId'=>1],['value'=>false],['packageId'=>1,'value'=>true,'extra'=>false],['packageId'=>1,'value'=>false,'resellerId'=>'*']] as $i=>$p)dic_ok('Missing or extra fields refused '.$i,dic_refuses(fn()=>DirectoryIndexingChange::params($p)));
    $id=1;$value=false;$p=DirectoryIndexingChange::params(['packageId'=>&$id,'value'=>&$value]);$id=2;$value=true;dic_ok('Parameter construction detaches caller references',$p===['packageId'=>1,'value'=>false]);
    dic_ok('Different operation cannot build this request',dic_refuses(fn()=>DirectoryIndexingChange::request(new ProviderOperation('packages.update','x',['packageId'=>1,'value'=>true]))));
    foreach(['GET','PUT','PATCH','DELETE'] as $method)dic_ok('Other method refused '.$method,dic_refuses(fn()=>DirectoryIndexingChange::wire(new TransportRequest($method,'https://api.20i.com/package/1/web/directoryIndexing',[],'{"value":true}',15))));
    $normalized=new TransportRequest('post','https://api.20i.com/package/1/web/directoryIndexing',[],'{"value":true}',15);DirectoryIndexingChange::wire($normalized);dic_ok('TransportRequest retains its established uppercase method normalization',$normalized->method==='POST');
    foreach(['http://api.20i.com/package/1/web/directoryIndexing','https://api.20i.com.evil.invalid/package/1/web/directoryIndexing','https://api.20i.com:443/package/1/web/directoryIndexing','https://user@api.20i.com/package/1/web/directoryIndexing','https://api.20i.com/package/01/web/directoryIndexing','https://api.20i.com/package/1/web/directoryIndexing?x=1','https://api.20i.com/package/1/web/directoryIndexing#x','https://api.20i.com/package/1/web/directoryIndexing/','https://api.20i.com/package/1/web/directoryindexing','https://api.20i.com/package/1/web/forceSSL','https://api.20i.com/package/1/web/%64irectoryIndexing'] as $i=>$url)dic_ok('Nonexact endpoint refused '.$i,dic_refuses(fn()=>DirectoryIndexingChange::wire(new TransportRequest('POST',$url,[],'{"value":true}',15))));
    foreach([null,'','true','[]','{}','{"value":null}','{"value":1}','{"value":"true"}','{"value":true,"value":false}','{"value":true,"other":false}','{"value": true}','{"Value":true}','{"value":false}\n'] as $i=>$body)dic_ok('Noncanonical or ambiguous body refused '.$i,dic_refuses(fn()=>DirectoryIndexingChange::wire(new TransportRequest('POST','https://api.20i.com/package/1/web/directoryIndexing',[],$body,15))));
    $register=new TwentyIOperationRegister();dic_ok('Generic owner approval cannot admit Directory listing',!$register->allowsGenericApproval(DirectoryIndexingChange::OPERATION,['packageId'=>1,'value'=>true]));
    $op=new ProviderOperation(DirectoryIndexingChange::OPERATION,'one-write',['packageId'=>1,'value'=>true]);
    foreach(['true','false','null','{"result":true}','{"result":1}','{}','[]','invalid'] as $i=>$body){$result=TwentyIResultClassifier::fromResponse($op->name,new TransportResponse(200,[],$body));dic_ok('HTTP 200 shape never acknowledges the change '.$i,$result->status===OperationResult::UNCERTAIN&&$result->externalId===null);}
    foreach([401,403,404,422] as $code){$result=TwentyIResultClassifier::fromResponse($op->name,new TransportResponse($code,[],'{}'));dic_ok('Post-send HTTP refusal is not success '.$code,$result->status===OperationResult::FAILED);}
    dic_ok('Force SSL operation cannot enter directory request construction',dic_refuses(fn()=>DirectoryIndexingChange::request(new ProviderOperation('packages.forcessl','isolated',['packageId'=>1,'value'=>true]))));
    dic_ok('Directory index file-name configuration cannot enter listing setter',dic_refuses(fn()=>DirectoryIndexingChange::wire(new TransportRequest('POST','https://api.20i.com/package/1/web/directoryIndex',[],'{"value":true}',15))));
    $mirror=__DIR__.'/../../site/includes/foundation/twentyi-operations/DirectoryIndexingChange.php';dic_ok('Shipping request contract matches canonical bytes',hash_file('sha256',$mirror)===hash_file('sha256',__DIR__.'/../../foundation/twentyi-operations/DirectoryIndexingChange.php'));
    echo json_encode(['passed'=>true,'checks'=>$checks],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL;
}catch(Throwable $e){echo json_encode(['passed'=>false,'checks'=>$checks,'error'=>$e->getMessage()],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL;exit(1);}
